import Foundation

/// Learning metadata describes practice and evidence, never accreditation or artistic rank.
public struct DegreeSource: Codable, Sendable, Identifiable {
    public let id: String
    public let title: String
    public let url: String
    public let kind: String
}

public struct DegreeLesson: Codable, Sendable, Identifiable {
    public let id: String
    public let title: String
    public let concept: String
    public let labID: String
    public let equation: String
    public let prediction: String
    public let creationTask: String
    public let modelLimit: String
    public let sourceIDs: [String]
    public let startingValues: [String: Double]
    public let steps: [String]
    public let explanation: String
    public let mathTask: String
    public let musicTask: String
}

public struct DegreeModule: Codable, Sendable, Identifiable {
    public let id: String
    public let title: String
    public let subtitle: String
    public let stage: Int
    public let prerequisiteIDs: [String]
    public let lessons: [DegreeLesson]
}

public struct DegreeProject: Codable, Sendable, Identifiable {
    public let id: String
    public let title: String
    public let brief: String
    public let requiredModuleIDs: [String]
    public let deliverables: [String]
    public let acceptanceCriteria: [String]
    public let modelLimit: String
    public let sourceIDs: [String]
}

public enum DegreeCurriculum {
    public static let scopeStatement = "A 48-lesson self-study path through music, mathematical relationships and sound physics, with four original fusion projects. Practice and saved evidence do not award a degree or establish musical mastery."
    public static let modules = foundationModules + materialModules + developmentModules
    public static var lessons: [DegreeLesson] { modules.flatMap(\.lessons) }
    public static func lesson(id: String) -> DegreeLesson? { lessons.first { $0.id == id } }
    public static func source(id: String) -> DegreeSource? { sources.first { $0.id == id } }

